'use client';

import React, { useRef, useState } from 'react';
import { db } from '../../lib/firebase';
import {
  collection,
  addDoc,
  setDoc,
  doc,
  onSnapshot,
  serverTimestamp
} from 'firebase/firestore';
import { getAuth } from 'firebase/auth';

const Home = () => {
  const localVideoRef = useRef<HTMLVideoElement>(null);
  const remoteVideoRef = useRef<HTMLVideoElement>(null);
  const [roomId, setRoomId] = useState('');
  const [roomName, setRoomName] = useState('');
  const [roomLimit, setRoomLimit] = useState<number | null>(null);
  const [peerConnection, setPeerConnection] = useState<RTCPeerConnection | null>(null);
  const [localStream, setLocalStream] = useState<MediaStream | null>(null);
  const [remoteStream, setRemoteStream] = useState<MediaStream | null>(null);

  const config = {
    iceServers: [
      {
        urls: [
          'stun:stun1.l.google.com:19302',
          'stun:stun2.l.google.com:19302',
        ],
      },
    ],
    iceCandidatePoolSize: 10,
  };

  async function startCamera() {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: true, audio: true });

      if (localVideoRef.current) {
        localVideoRef.current.srcObject = stream;
      }

      const remote = new MediaStream();
      if (remoteVideoRef.current) {
        remoteVideoRef.current.srcObject = remote;
      }

      setLocalStream(stream);
      setRemoteStream(remote);
    } catch (error: any) {
      console.error("Error accessing media devices:", error);
      if (error.name === 'NotAllowedError' || error.name === 'PermissionDeniedError') {
        alert('⚠️ Accès refusé à la caméra/micro.');
      } else if (error.name === 'NotFoundError') {
        alert('🚫 Aucun périphérique trouvé.');
      } else {
        alert('❌ Erreur inconnue lors de l’accès aux périphériques.');
      }
    }
  }

  async function createRoom() {
    const auth = getAuth();
    const user = auth.currentUser;

    /*if (!user) {
      alert("🛑 Vous devez être connecté pour créer une room.");
      return;
    }*/

    if (!localStream) {
      alert('📷 Veuillez d’abord démarrer la caméra.');
      return;
    }

    const pc = new RTCPeerConnection(config);
    setPeerConnection(pc);

    localStream.getTracks().forEach((track) => {
      pc.addTrack(track, localStream);
    });

    const roomDocRef = doc(collection(db, 'rooms'));
    setRoomId(roomDocRef.id);

    const callerCandidatesCollection = collection(roomDocRef, 'callerCandidates');

    pc.addEventListener('icecandidate', async event => {
      if (event.candidate) {
        await addDoc(callerCandidatesCollection, event.candidate.toJSON());
      }
    });

    const offer = await pc.createOffer();
    await pc.setLocalDescription(offer);

    const roomData = {
      id: roomDocRef.id,
      ownerId: user.uid,
      createdAt: serverTimestamp(),
      RoomName: roomName || 'Room sans nom',
      ...(roomLimit ? { limit: roomLimit } : {}),
      participants: [user.uid],
      offer: {
        type: offer.type,
        sdp: offer.sdp,
      },
    };

    await setDoc(roomDocRef, roomData);

    onSnapshot(roomDocRef, async snapshot => {
      const data = snapshot.data();
      if (!pc.currentRemoteDescription && data?.answer) {
        const answer = new RTCSessionDescription(data.answer);
        await pc.setRemoteDescription(answer);
      }
    });

    const calleeCandidatesCollection = collection(roomDocRef, 'calleeCandidates');
    onSnapshot(calleeCandidatesCollection, snapshot => {
      snapshot.docChanges().forEach(change => {
        if (change.type === 'added') {
          const data = change.doc.data();
          pc.addIceCandidate(new RTCIceCandidate(data));
        }
      });
    });

    pc.addEventListener('track', event => {
      event.streams[0].getTracks().forEach(track => {
        remoteStream?.addTrack(track);
      });
    });
  }

  return (
    <div className="p-4">
      <h1 className="text-xl font-bold mb-4">🎥 WebRTC Chat with Next.js</h1>

      <div className="flex gap-4">
        <video ref={localVideoRef} autoPlay muted className="w-1/2 border rounded" />
        <video ref={remoteVideoRef} autoPlay className="w-1/2 border rounded" />
      </div>

      <div className="mt-4 flex flex-col sm:flex-row gap-2 sm:items-center">
        <button onClick={startCamera} className="bg-blue-500 text-white px-4 py-2 rounded">
          🎬 Start Camera
        </button>

        <input
          type="text"
          placeholder="Nom de la salle"
          value={roomName}
          onChange={(e) => setRoomName(e.target.value)}
          className="border p-2 rounded w-full sm:w-auto"
        />

        <input
          type="number"
          value={roomLimit ?? ''}
          onChange={e => {
            const value = e.target.value;
            setRoomLimit(value ? parseInt(value) : null);
          }}
          placeholder="Limite participants (facultatif)"
          className="border p-2 rounded w-full sm:w-auto"
          min={2}
          max={20}
        />

        <button onClick={createRoom} className="bg-green-500 text-white px-4 py-2 rounded">
          ➕ Create Room
        </button>

        {roomId && <p className="ml-4 text-sm">Room ID: <strong>{roomId}</strong></p>}
      </div>
    </div>
  );
};

export default Home;
